base.apps/service/src/features/booking/pricin:
/** Стоимость записи в копейках: скидка в процентах от базовой цены. */
export function applyDiscount(priceCents: number, percent: number): number {
  const discount = Math.floor((priceCents * percent) / 100);
  return priceCents - discount;
}

